    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 v) public {
        require(v <= c.balanceOf(address(this)));
        bool reverted;
        bool success;
        bool s = c.burn(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            success = s;
            reverted = false;
        }
        assert(reverted || success);
    }
}

