pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 v) internal {
        vm.assume(v <= c.balanceOf(address(this)));
        bool reverted;
        bool success;
        try c.burn(v) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || success);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
